        "lead": "cRPO 재가속 평가와 AI 에이전트 Identity 서사가 겹치며 6M 절대 상승률 154.83%의 추세가 형성됐다. 다만 상승의 상당 부분이 마진 레버리지와 테마 재평가에 기대고 있어 매출 성장률(10~11%대) 자체는 정체 구간이다. 성장 재가속이 후속 분기 수치로 확인되는지가 논리의 성립 조건이다.",
