            "statement": "2026-06-30 분기 매출 $696.1M, YoY +35.9%로 직전 3개 분기(+30.7%, +33.6%, +33.5%) 대비 성장률이 가속됐다. 이는 상승의 펀더멘털 근거로 가장 확실하다.",
